/** Backend base URL (no trailing slash). Example: http://localhost:4000 */
export const API_ORIGIN = (
  process.env.REACT_APP_API_URL || 'http://localhost:4000'
).replace(/\/$/, '');

export function apiUrl(path) {
  const p = path.startsWith('/') ? path : `/${path}`;
  return `${API_ORIGIN}${p}`;
}
